CREATE TYPE public.app_role AS ENUM ('admin','sales');
CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, name text NOT NULL DEFAULT 'Comercial');
GRANT SELECT,UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.user_roles (user_id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL DEFAULT 'sales');
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
CREATE POLICY profiles_read ON public.profiles FOR SELECT TO authenticated USING(id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY profiles_edit ON public.profiles FOR UPDATE TO authenticated USING(id=auth.uid()) WITH CHECK(id=auth.uid());
CREATE POLICY roles_read ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.new_sales_user() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,name) VALUES(NEW.id,COALESCE(NEW.raw_user_meta_data->>'name','Comercial')); INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id,'sales'); RETURN NEW; END $$;
CREATE TRIGGER sales_user_created AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.new_sales_user();
CREATE TABLE public.leads (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company text NOT NULL, decision_maker text NOT NULL DEFAULT '', phone text NOT NULL DEFAULT '', instagram text NOT NULL DEFAULT '', city text NOT NULL DEFAULT '', state text NOT NULL DEFAULT '', source text NOT NULL DEFAULT 'WhatsApp', channel text NOT NULL DEFAULT 'WhatsApp' CHECK(channel IN ('WhatsApp','Instagram')), stage integer NOT NULL DEFAULT 0 CHECK(stage BETWEEN 0 AND 8), pain text NOT NULL DEFAULT '', current_system text NOT NULL DEFAULT '', next_action text NOT NULL DEFAULT '', next_at timestamptz, owner_id uuid REFERENCES public.profiles(id), segment text NOT NULL DEFAULT 'Fábrica de produtos de limpeza e saneantes', revenue text NOT NULL DEFAULT '', employees text NOT NULL DEFAULT '', buying_trigger text NOT NULL DEFAULT '', qualification jsonb NOT NULL DEFAULT '[false,false,false,false,false]', unread integer NOT NULL DEFAULT 0, resolved boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.leads TO authenticated; GRANT ALL ON public.leads TO service_role;
ALTER TABLE public.leads ENABLE ROW LEVEL SECURITY;
CREATE INDEX leads_owner ON public.leads(owner_id);
CREATE POLICY leads_access ON public.leads FOR ALL TO authenticated USING(owner_id=auth.uid() OR public.has_role(auth.uid(),'admin')) WITH CHECK(owner_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.can_access_lead(_lead uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.leads WHERE id=_lead AND (owner_id=auth.uid() OR public.has_role(auth.uid(),'admin'))) $$;
CREATE FUNCTION public.guard_lead_owner() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF TG_OP='UPDATE' AND NEW.owner_id IS DISTINCT FROM OLD.owner_id AND auth.uid() IS NOT NULL AND NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Somente administradores podem alterar responsáveis'; END IF; RETURN NEW; END $$;
CREATE TRIGGER lead_owner_guard BEFORE UPDATE ON public.leads FOR EACH ROW EXECUTE FUNCTION public.guard_lead_owner();
CREATE TABLE public.contacts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), lead_id uuid NOT NULL REFERENCES public.leads ON DELETE CASCADE, name text NOT NULL, phone text NOT NULL DEFAULT '', instagram text NOT NULL DEFAULT '');
GRANT SELECT,INSERT,UPDATE,DELETE ON public.contacts TO authenticated; GRANT ALL ON public.contacts TO service_role; ALTER TABLE public.contacts ENABLE ROW LEVEL SECURITY;
CREATE POLICY contacts_access ON public.contacts FOR ALL TO authenticated USING(public.can_access_lead(lead_id)) WITH CHECK(public.can_access_lead(lead_id));
CREATE TABLE public.conversations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), lead_id uuid NOT NULL REFERENCES public.leads ON DELETE CASCADE, channel text NOT NULL, integration_status text NOT NULL DEFAULT 'disconnected', external_id text, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.conversations TO authenticated; GRANT ALL ON public.conversations TO service_role; ALTER TABLE public.conversations ENABLE ROW LEVEL SECURITY;
CREATE POLICY conversations_access ON public.conversations FOR ALL TO authenticated USING(public.can_access_lead(lead_id)) WITH CHECK(public.can_access_lead(lead_id));
CREATE TABLE public.messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), lead_id uuid NOT NULL REFERENCES public.leads ON DELETE CASCADE, conversation_id uuid REFERENCES public.conversations ON DELETE CASCADE, content text NOT NULL, direction text NOT NULL DEFAULT 'inbound' CHECK(direction IN ('inbound','outbound')), status text NOT NULL DEFAULT 'simulated' CHECK(status IN ('simulated','draft','received','sent','failed')), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.messages TO authenticated; GRANT ALL ON public.messages TO service_role; ALTER TABLE public.messages ENABLE ROW LEVEL SECURITY;
CREATE POLICY messages_read ON public.messages FOR SELECT TO authenticated USING(public.can_access_lead(lead_id));
CREATE TABLE public.activities (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), lead_id uuid NOT NULL REFERENCES public.leads ON DELETE CASCADE, type text NOT NULL DEFAULT 'Follow-up', title text NOT NULL, due_at timestamptz NOT NULL DEFAULT now(), owner_id uuid REFERENCES public.profiles, status text NOT NULL DEFAULT 'pendente' CHECK(status IN ('pendente','concluída','cancelada')), observation text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.activities TO authenticated; GRANT ALL ON public.activities TO service_role; ALTER TABLE public.activities ENABLE ROW LEVEL SECURITY;
CREATE POLICY activities_access ON public.activities FOR ALL TO authenticated USING(public.can_access_lead(lead_id)) WITH CHECK(public.can_access_lead(lead_id));
CREATE TABLE public.notes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), lead_id uuid NOT NULL REFERENCES public.leads ON DELETE CASCADE, content text NOT NULL, author_id uuid, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.notes TO authenticated; GRANT ALL ON public.notes TO service_role; ALTER TABLE public.notes ENABLE ROW LEVEL SECURITY;
CREATE POLICY notes_read ON public.notes FOR SELECT TO authenticated USING(public.can_access_lead(lead_id)); CREATE POLICY notes_create ON public.notes FOR INSERT TO authenticated WITH CHECK(public.can_access_lead(lead_id) AND author_id=auth.uid());
CREATE TABLE public.stage_history (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), lead_id uuid NOT NULL REFERENCES public.leads ON DELETE CASCADE, from_stage integer, to_stage integer NOT NULL, author_id uuid, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.stage_history TO authenticated; GRANT ALL ON public.stage_history TO service_role; ALTER TABLE public.stage_history ENABLE ROW LEVEL SECURITY;
CREATE POLICY stage_history_read ON public.stage_history FOR SELECT TO authenticated USING(public.can_access_lead(lead_id));
CREATE FUNCTION public.audit_lead() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF TG_OP='INSERT' THEN INSERT INTO public.activities(lead_id,type,title,status,owner_id) VALUES(NEW.id,'Registro','Lead cadastrado','concluída',NEW.owner_id); ELSIF NEW.stage IS DISTINCT FROM OLD.stage THEN INSERT INTO public.stage_history(lead_id,from_stage,to_stage,author_id) VALUES(NEW.id,OLD.stage,NEW.stage,auth.uid()); INSERT INTO public.activities(lead_id,type,title,status,owner_id) VALUES(NEW.id,'Etapa','Etapa atualizada','concluída',NEW.owner_id); ELSIF to_jsonb(NEW) - ARRAY['unread','resolved'] IS DISTINCT FROM to_jsonb(OLD) - ARRAY['unread','resolved'] THEN INSERT INTO public.activities(lead_id,type,title,status,owner_id) VALUES(NEW.id,'Atualização','Perfil do lead atualizado','concluída',NEW.owner_id); END IF; RETURN NEW; END $$;
CREATE TRIGGER lead_audit AFTER INSERT OR UPDATE ON public.leads FOR EACH ROW EXECUTE FUNCTION public.audit_lead();
