INSERT INTO public.conversations(lead_id,channel) SELECT id,channel FROM public.leads;
INSERT INTO public.messages(lead_id,conversation_id,content,direction,created_at) SELECT l.id,c.id,'Olá, '||split_part(l.decision_maker,' ',1)||'! Sou a Camila, do FindFlow. Como vocês organizam a gestão da fábrica hoje?','outbound',now()-interval '2 hours' FROM public.leads l JOIN public.conversations c ON c.lead_id=l.id;
INSERT INTO public.messages(lead_id,conversation_id,content,created_at) SELECT l.id,c.id,'Olá! Hoje usamos '||lower(l.current_system)||'. Nosso maior desafio é '||lower(l.pain)||'.',now()-interval '1 hour' FROM public.leads l JOIN public.conversations c ON c.lead_id=l.id;
INSERT INTO public.messages(lead_id,conversation_id,content,direction,created_at) SELECT l.id,c.id,'Entendi, Marcos! O FindFlow conecta produção, estoque e vendas em um só lugar. Podemos conversar sobre a realidade da Brisa?','outbound',now()-interval '35 minutes' FROM public.leads l JOIN public.conversations c ON c.lead_id=l.id WHERE l.id='00000000-0000-4000-8000-000000000001';
INSERT INTO public.messages(lead_id,conversation_id,content,created_at) SELECT l.id,c.id,'Podemos sim! Vocês conseguem controlar as fórmulas e os lotes também?',now()-interval '12 minutes' FROM public.leads l JOIN public.conversations c ON c.lead_id=l.id WHERE l.id='00000000-0000-4000-8000-000000000001';
INSERT INTO public.activities(lead_id,type,title,due_at,owner_id) SELECT id, CASE WHEN stage=4 THEN 'Demonstração' WHEN stage=2 THEN 'Diagnóstico' ELSE 'Follow-up' END,next_action,next_at,owner_id FROM public.leads WHERE next_at IS NOT NULL;